package org.brightstats.desktop;
import java.util.*;import com.google.gson.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.geometry.Insets;import javafx.stage.Window;import org.brightstats.stats.*;import org.brightstats.data.*;
final class SensitivityDialog {
 private SensitivityDialog(){}
 enum Mode { INFLUENCE, MULTIVERSE }
 record Settings(Mode mode,List<SemSensitivity.Candidate> candidates,SemSensitivity.InfluenceOptions influence,int clusterColumn,String clusterName,boolean completeCases){Settings{Objects.requireNonNull(mode);candidates=List.copyOf(candidates);Objects.requireNonNull(influence);if(candidates.isEmpty()||candidates.size()>20||mode==Mode.MULTIVERSE&&candidates.size()<2||mode==Mode.INFLUENCE&&influence.unit()==SemSensitivity.Unit.CLUSTER&&(clusterColumn<0||clusterName==null||clusterName.isBlank()))throw new IllegalArgumentException("Configure the reference/model alternatives and any required cluster source binding.");}SemModel.Model reference(){return candidates.getFirst().model();}}
 static Settings read(JsonElement value){if(value==null||value.isJsonNull())return null;var o=StatisticalInput.object(value,Set.of("mode","candidates","influence","clusterColumn","clusterName","completeCases"),"sensitivity studio settings",false);return new Settings(StatisticalInput.enumeration(o,"mode",Mode.class,Mode.INFLUENCE),SensitivityInput.candidates(o.get("candidates")),SensitivityInput.influence(o.get("influence")),StatisticalInput.integer(o,"clusterColumn",-1),o.has("clusterName")?StatisticalInput.text(o.get("clusterName")):"",StatisticalInput.bool(o,"completeCases",false));}
 static Optional<Settings> show(Window owner,List<String> sourceNames,SemModel.Model reference,Settings previous){return new Editor(owner,sourceNames,reference,previous).dialog.showAndWait();}
 private static final class CandidateEditor extends VBox {
  final TextField name=new TextField();final TextArea model=new TextArea();
  CandidateEditor(SemSensitivity.Candidate candidate){super(6);name.setText(candidate.name());name.setAccessibleText("Specification name");model.setText(new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(candidate.model()));model.setPrefRowCount(10);model.setAccessibleText("Explicit RAM specification: "+candidate.name());getChildren().addAll(new Label("Specification name"),name,model);setPadding(new Insets(10));}
  SemSensitivity.Candidate read(FimlSem.Options options){return new SemSensitivity.Candidate(name.getText().strip(),SemModelInput.model(BoundedJson.parse(model.getText())),options);}
 }
 private static final class Editor {
  final Dialog<Settings> dialog=new Dialog<>();final TabPane modes=new TabPane();final ComboBox<SemSensitivity.Unit> unit=new ComboBox<>();final ComboBox<String> cluster=new ComboBox<>();final TextArea selection=new TextArea(),reference=new TextArea();final TextField maximum=new TextField("1000"),iterations=new TextField("1500"),confidence=new TextField("0.95");final CheckBox complete=new CheckBox("Use one explicitly selected complete-case sample for every specification");final VBox alternatives=new VBox(10);final List<CandidateEditor> editors=new ArrayList<>();final Label error=new Label();final List<String> headers;Settings result;
  Editor(Window owner,List<String> sourceNames,SemModel.Model model,Settings previous){headers=List.copyOf(sourceNames);dialog.initOwner(owner);dialog.setTitle("Influence and specification studio");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);unit.getItems().setAll(SemSensitivity.Unit.values());unit.setValue(previous==null?SemSensitivity.Unit.CASE:previous.influence().unit());unit.setAccessibleText("Deletion unit");cluster.getItems().setAll(headers);cluster.setAccessibleText("Cluster-ID original source column");if(previous!=null&&previous.clusterColumn()>=0&&previous.clusterColumn()<headers.size()&&headers.get(previous.clusterColumn()).equals(previous.clusterName()))cluster.getSelectionModel().select(previous.clusterColumn());else cluster.getSelectionModel().selectFirst();if(previous!=null){maximum.setText(Integer.toString(previous.influence().maximumRefits()));selection.setText(String.join("\n",previous.influence().selectedUnits()));iterations.setText(Integer.toString(previous.influence().estimator().maxIterations()));confidence.setText(Double.toString(previous.influence().estimator().confidence()));complete.setSelected(previous.completeCases());}selection.setPrefRowCount(5);selection.setPromptText("Blank: all units. Otherwise one original row number or exact cluster label per line.");selection.setAccessibleText("Explicit deletion units");reference.setText(new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(model));reference.setPrefRowCount(12);reference.setAccessibleText("Reference RAM model");
   Label note=new Label("Exact deletion refits diagnose sensitivity without editing your data. Whole-cluster mode removes all members together. The specification studio compares a prespecified set on the same observed variables and source sample; it retains failed alternatives and does not pool exploratory P values. Named-variable parameter locations distinguish different estimands. Each requested refit may take time; the cap never silently samples units.");note.setWrapText(true);note.setMaxWidth(900);VBox deletion=new VBox(10,new Label("Deletion unit"),unit,new Label("Cluster source column (cluster mode only)"),cluster,new Label("Explicit units, one per line"),selection,new Label("Maximum deletion refits (1–2,000)"),maximum,new Label("Reference model"),reference);deletion.setPadding(new Insets(10));
   var options=previous==null?FimlSem.Options.defaults():previous.influence().estimator();if(previous!=null&&previous.mode()==Mode.MULTIVERSE)for(var candidate:previous.candidates())add(candidate);else{add(new SemSensitivity.Candidate("Baseline",model,options));add(new SemSensitivity.Candidate("Fix one parameter",constrained(model),options));}Button append=new Button("Add specification copied from reference");append.setOnAction(e->{if(editors.size()>=20){error.setText("At most 20 specifications are supported.");return;}add(new SemSensitivity.Candidate("Specification "+(editors.size()+1),model,options));});VBox multi=new VBox(10,complete,new Label("Shared estimator controls below apply to every edited specification."),append,alternatives);multi.setPadding(new Insets(10));Tab influenceTab=new Tab("Exact deletion influence",new ScrollPane(deletion)),multiTab=new Tab("Prespecified alternatives",new ScrollPane(multi));influenceTab.setClosable(false);multiTab.setClosable(false);modes.getTabs().setAll(influenceTab,multiTab);modes.getSelectionModel().select(previous!=null&&previous.mode()==Mode.MULTIVERSE?1:0);error.setWrapText(true);VBox content=new VBox(10,note,modes,new HBox(10,new Label("Maximum optimizer iterations"),iterations,new Label("Interval confidence"),confidence),error);content.setPadding(new Insets(12));content.setPrefSize(950,700);VBox.setVgrow(modes,Priority.ALWAYS);dialog.getDialogPane().setContent(content);
   dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{var estimator=new FimlSem.Options(Integer.parseInt(iterations.getText().strip()),1e-8,1e-12,Double.parseDouble(confidence.getText().strip()));var influence=new SemSensitivity.InfluenceOptions(unit.getValue(),selection.getText().lines().map(String::strip).filter(s->!s.isBlank()).toList(),Integer.parseInt(maximum.getText().strip()),estimator);Mode mode=modes.getSelectionModel().getSelectedIndex()==0?Mode.INFLUENCE:Mode.MULTIVERSE;List<SemSensitivity.Candidate> selected=mode==Mode.INFLUENCE?List.of(new SemSensitivity.Candidate("Reference",SemModelInput.model(BoundedJson.parse(reference.getText())),estimator)):editors.stream().map(e->e.read(estimator)).toList();if(new HashSet<>(selected.stream().map(SemSensitivity.Candidate::name).toList()).size()!=selected.size())throw new IllegalArgumentException("Use distinct specification names.");result=new Settings(mode,selected,influence,cluster.getSelectionModel().getSelectedIndex(),Objects.toString(cluster.getValue(),""),complete.isSelected());}catch(RuntimeException invalid){error.setText(invalid.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);
  }
  void add(SemSensitivity.Candidate candidate){var editor=new CandidateEditor(candidate);Button remove=new Button("Remove specification");VBox body=new VBox(6,editor,remove);TitledPane panel=new TitledPane(candidate.name(),body);panel.setAnimated(false);panel.setExpanded(editors.size()<2);remove.setOnAction(e->{editors.remove(editor);alternatives.getChildren().remove(panel);});editors.add(editor);alternatives.getChildren().add(panel);}
 }
 static SemModel.Model constrained(SemModel.Model model){if(model.parameters().isEmpty())return model;var parameter=model.parameters().stream().filter(p->p.locations().stream().allMatch(l->l.kind()==SemModel.Kind.DIRECTED)).findFirst().orElse(model.parameters().getFirst());double[][] a=model.directed(),s=model.covariance();double[] m=model.intercepts();for(var l:parameter.locations())switch(l.kind()){case DIRECTED->a[l.row()][l.column()]=0;case INTERCEPT->m[l.row()]=0;case COVARIANCE->{s[l.row()][l.column()]=parameter.start();s[l.column()][l.row()]=parameter.start();}}return new SemModel.Model(model.variables(),model.observed(),a,s,m,model.parameters().stream().filter(p->!p.name().equals(parameter.name())).toList());}
 static Settings smoke(Window owner,List<String> sourceNames,Settings current){var editor=new Editor(owner,sourceNames,current.reference(),current);editor.dialog.show();editor.maximum.setText("0");((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!editor.dialog.isShowing())throw new AssertionError("Zero refit cap accepted");editor.maximum.setText(Integer.toString(current.influence().maximumRefits()));((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();return Objects.requireNonNull(editor.dialog.getResult());}
}
